#include <stdio.h>
#include <string.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int dir[61], esq[61];
    memset(dir, 0, sizeof(dir));
    memset(esq, 0, sizeof(esq));

    for (int i = 0; i < n; i++) {
        int m;
        char l;
        scanf("%d %c", &m, &l);
        if (l == 'D') dir[m]++;
        else esq[m]++;
    }

    int total = 0;
    for (int m = 30; m <= 60; m++) {
        total += (dir[m] < esq[m]) ? dir[m] : esq[m];
    }

    printf("%d\n", total);
    return 0;
}
